-- F-052: Classic Instance Tuning - DBC spell overrides
-- Applied after [BASE,F-044]_spell.sql
--
-- Mr. Smite (Deadmines) stun duration reductions
-- Petrify (Archaedas, Uldaman) duration reduction
-- Hex of Jammal'an (Sunken Temple) - changed from instant to interruptible cast
-- Razorlash (Maraudon) custom spells: Razor Thorns + Rejuvenation

-- ============================================================================
-- Mr. Smite - Reduced stun durations (originally 10s each)
-- ============================================================================

-- Smite Stomp (6432): 10s → 3.5s (duration_index 1 → 551)
UPDATE `dbc`.`spell` SET `duration_index` = 551 WHERE `id` = 6432;

-- Smite Slam (6435): 10s → 1s (duration_index 1 → 36)
UPDATE `dbc`.`spell` SET `duration_index` = 36 WHERE `id` = 6435;

-- ============================================================================
-- Petrify (11020) - Zul'Farrak Basilisks - Reduced duration (originally 8s)
-- ============================================================================

-- Petrify: 8s → 3s (duration_index 28 → 27)
UPDATE `dbc`.`spell` SET `duration_index` = 27 WHERE `id` = 11020;

-- ============================================================================
-- Hex of Jammal'an (12479) - Sunken Temple
-- Changed from instant to 3s interruptible cast
-- ============================================================================

UPDATE `dbc`.`spell` SET `cast_time_index` = 14, `prevention_type` = 1 WHERE `id` = 12479;

-- ============================================================================
-- Razorlash (12258) - Maraudon - Custom spells
-- ============================================================================

